/**
 *
 * FileUploadTrigger is a button component that opens the file dialog when clicked.
 *
 * [Live Demo](https://www.primereact.org/fileupload/)
 *
 * @module FileUploadTrigger
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { FileUploadRootInstance } from './FileUploadRoot.types';
/**
 * Defines passthrough(pt) options type in FileUploadTrigger component.
 */
export type FileUploadTriggerPassThroughType<E> = PassThroughType<FileUploadTriggerInstance, E>;
/**
 * Defines passthrough(pt) options of FileUploadTrigger component.
 */
export interface FileUploadTriggerPassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: FileUploadTriggerPassThroughType<React.HTMLAttributes<HTMLButtonElement>>;
}
/**
 * Defines valid properties in FileUploadTrigger component.
 */
export interface FileUploadTriggerProps extends BaseComponentProps<FileUploadTriggerInstance, unknown, FileUploadTriggerPassThrough> {
}
/**
 * Defines valid state in FileUploadTrigger component.
 */
export interface FileUploadTriggerState {
}
/**
 * Defines the methods and properties exposed by FileUploadTrigger component.
 */
export interface FileUploadTriggerExposes {
    /**
     * Instance of the FileUpload component.
     */
    fileupload: FileUploadRootInstance | undefined | null;
}
/**
 * Instance of FileUploadTrigger component.
 */
export type FileUploadTriggerInstance = ComponentInstance<FileUploadTriggerProps, FileUploadTriggerState, FileUploadTriggerExposes>;
